import flax.linen as nn
import jax.numpy as jnp
import optax

# --- Loss & RC Head (from SOTA) ---
def compute_loss(predictions, targets, params, x):
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    curv_pen = jnp.mean(curv * curv)
    return mae + 1e-4 * curv_pen

class ResidualCopyHead(nn.Module):
    @nn.compact
    def __call__(self, x):
        num_neurons = x.shape[2]
        x_flat = x.transpose(0, 2, 1).reshape(-1, 4)
        residual = nn.Dense(32)(x_flat)
        residual = residual.reshape(x.shape[0], num_neurons, 32).transpose(0, 2, 1)
        output = jnp.zeros((x.shape[0], 32, num_neurons))
        output = output.at[:, :4, :].set(x)
        return output + residual

# --- New Self-Attention Core ---
class SelfAttentionForecaster(nn.Module):
    rank_k: int

    @nn.compact
    def __call__(self, factors_in, training: bool = False):
        # Add positional encoding
        pos = self.param('pos_embedding', nn.initializers.normal(stddev=0.02), (factors_in.shape[1], self.rank_k))
        x = factors_in + pos[None, :, :]

        # Single Transformer Encoder Block
        x_norm = nn.LayerNorm()(x)
        attn_output = nn.SelfAttention(num_heads=8)(x_norm)
        x = x + nn.Dropout(0.1)(attn_output, deterministic=not training)

        ffn_output = nn.Dense(self.rank_k * 4)(x)
        ffn_output = nn.relu(ffn_output)
        ffn_output = nn.Dense(self.rank_k)(ffn_output)
        x = x + nn.Dropout(0.1)(ffn_output, deterministic=not training)

        # Forecasting head
        x_flat = x.reshape((x.shape[0], -1))
        factors_out_flat = nn.Dense(32 * self.rank_k)(x_flat)
        return factors_out_flat.reshape((x.shape[0], 32, self.rank_k))

# --- Full Model ---
class SAF_Model(nn.Module):
    rank_k: int
    proj_rank: int

    @nn.compact
    def __call__(self, x, training: bool = False):
        U = self.param('U', nn.initializers.lecun_normal(), (71721, self.proj_rank))
        V = self.param('V', nn.initializers.lecun_normal(), (self.rank_k, self.proj_rank))
        U_eff = U / (jnp.linalg.norm(U, axis=0, keepdims=True) + 1e-6)
        factors_in = jnp.einsum('btn,np->btp', x, U_eff) @ V.T

        factors_out = SelfAttentionForecaster(rank_k=self.rank_k)(factors_in, training=training)

        factors_out_norm = nn.LayerNorm()(factors_out)
        y_factor = (factors_out_norm @ V) @ U_eff.T
        y_copy = ResidualCopyHead()(x)
        return y_factor + y_copy

# --- Boilerplate ---
def _define_hyperparameters():
    return { 'learning_rate': 0.001, 'rank_k': 320, 'proj_rank': 32 }

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adam(learning_rate=learning_rate))

def create_network(hparams):
    class ModelWrapper:
        def __init__(self, hparams):
            self.model = SAF_Model(rank_k=hparams['rank_k'], proj_rank=hparams['proj_rank'])
            self.needs_rng = True
        def init(self, rng, dummy_input): return self.model.init({'params': rng, 'dropout': rng}, dummy_input)
        def apply(self, params, x, training=False, rngs=None): return self.model.apply(params, x, training=training, rngs=rngs)
    return ModelWrapper(hparams)
